"""Independent checker mimicking the spec's acceptance tests."""
import numpy as np
from scipy.optimize import linprog

def build(req):
    edges = req["edges"]; comms = req["commodities"]
    failed = set(req.get("failed_edges", []))
    M=len(edges)
    flat=[]
    for k,c in enumerate(comms):
        for pi,p in enumerate(c["paths"]):
            a=c["demand"]*c["previous"][pi]/16.0
            live = not any(e in failed for e in p)
            flat.append((k,p,a,live))
    P=len(flat); K=len(comms); nv=2*P+1
    xi=lambda j:j; ti=lambda j:P+j; ui=2*P
    # A_ub dense
    R=M+3*P+2
    A=np.zeros((R,nv)); b=np.zeros(R)
    # edge rows
    for e in range(M):
        for j,(k,p,a,live) in enumerate(flat):
            if e in p: A[e,xi(j)]+=1
        A[e,ui]=-edges[e]["capacity"]; b[e]=0
    base=M
    for j,(k,p,a,live) in enumerate(flat):
        r1=base+2*j; r2=base+2*j+1
        A[r1,xi(j)]=1; A[r1,ti(j)]=-1; b[r1]=a
        A[r2,xi(j)]=-1; A[r2,ti(j)]=-1; b[r2]=-a
    base=M+2*P
    for j,(k,p,a,live) in enumerate(flat):
        A[base+j,xi(j)]=1
        b[base+j]=comms[k]["demand"] if live else 0.0
    base=M+3*P
    for j in range(P): A[base,ti(j)]=1
    b[base]=2*req["budget"]
    A[base+1,ui]=1; b[base+1]=1.0
    E=np.zeros((K,nv)); d=np.zeros(K)
    for j,(k,p,a,live) in enumerate(flat): E[k,xi(j)]+=1
    for k,c in enumerate(comms): d[k]=c["demand"]
    c=np.zeros(nv); c[ui]=1
    a_arr=np.array([f[2] for f in flat])
    return dict(M=M,P=P,K=K,nv=nv,R=R,A=A,b=b,E=E,d=d,c=c,flat=flat,a=a_arr,
                edges=edges,comms=comms)

def primal_opt(B):
    res=linprog(B["c"],A_ub=B["A"],b_ub=B["b"],A_eq=B["E"],b_eq=B["d"],
                bounds=[(0,None)]*B["nv"],method="highs")
    return res

def check(req, resp, verbose=False):
    B=build(req)
    M,P,K,nv,R=B["M"],B["P"],B["K"],B["nv"],B["R"]
    errs=[]
    if resp.get("status")=="invalid":
        return ["planner returned invalid"], {}
    # independent decision
    pres=primal_opt(B)
    opt_infeasible = (pres.status==2)
    if resp["status"]=="optimal":
        if opt_infeasible:
            errs.append("claimed optimal but LP infeasible")
            return errs,{}
        flows=resp["flows"]
        # flatten
        x=[]
        for k,c in enumerate(B["comms"]):
            if len(flows[k])!=len(c["paths"]):
                errs.append("flows shape mismatch"); return errs,{}
            x.extend(flows[k])
        x=np.array(x,dtype=float)
        if len(x)!=P:
            errs.append("flows total mismatch"); return errs,{}
        a=B["a"]
        t=np.abs(x-a)
        U=resp["mlu"]
        v=np.concatenate([x,t,[U]])
        if np.any(v < -1e-7): errs.append("primal var < -1e-7")
        # equalities
        r=E_res=np.abs(B["E"]@v - B["d"])
        if np.max(r) > 1e-5: errs.append("eq residual %g"%np.max(r))
        r2=B["A"]@v - B["b"]
        if np.max(r2) > 1e-5: errs.append("ineq residual %g"%np.max(r2))
        # loads
        loads=np.array(resp["loads"],dtype=float)
        if len(loads)!=M: errs.append("loads len")
        Lcheck=np.zeros(M)
        for e in range(M):
            for j,(k,p,aa,live) in enumerate(B["flat"]):
                if e in p: Lcheck[e]+=x[j]
        if M>0 and np.max(np.abs(Lcheck-loads))>1e-5: errs.append("load inconsistency %g"%np.max(np.abs(Lcheck-loads)))
        # migration
        mig=0.5*np.sum(np.abs(x-a))
        if abs(mig-resp["migration"])>1e-5: errs.append("migration inconsistency %g"%abs(mig-resp["migration"]))
        # actual mlu
        if M==0:
            amlu=0.0
        else:
            amlu=max(loads[e]/B["edges"][e]["capacity"] for e in range(M))
        if abs(amlu-resp["mlu"])>1e-5: errs.append("actual mlu inconsistency %g vs %g"%(amlu,resp["mlu"]))
        # dual
        y=np.array(resp["dual"]["inequality"],dtype=float)
        q=np.array(resp["dual"]["equality"],dtype=float)
        if len(y)!=R: errs.append("dual y len")
        if len(q)!=K: errs.append("dual q len")
        if np.any(y>1e-7): errs.append("y>1e-7 max %g"%np.max(y))
        dual_col=B["A"].T@y + B["E"].T@q - B["c"]
        if np.max(dual_col) > 1e-7: errs.append("dual col residual %g"%np.max(dual_col))
        Lval=B["b"]@y + B["d"]@q
        if abs(resp["mlu"]-Lval)>2e-5: errs.append("mlu-L %g"%(resp["mlu"]-Lval))
        if abs(resp["mlu"]-pres.fun)>2e-5: errs.append("mlu-opt %g"%(resp["mlu"]-pres.fun))
        return errs, {"opt":pres.fun,"mlu":resp["mlu"]}
    elif resp["status"]=="infeasible":
        if not opt_infeasible:
            errs.append("claimed infeasible but LP optimal=%g"%pres.fun)
            return errs,{}
        y=np.array(resp["certificate"]["inequality"],dtype=float)
        q=np.array(resp["certificate"]["equality"],dtype=float)
        if len(y)!=R: errs.append("cert y len")
        if len(q)!=K: errs.append("cert q len")
        if np.any(y>1e-7): errs.append("cert y>1e-7 max %g"%np.max(y))
        col=B["A"].T@y + B["E"].T@q
        if np.max(col) > 1e-7: errs.append("cert col residual %g"%np.max(col))
        val=B["b"]@y + B["d"]@q
        if abs(val-1.0)>1e-5: errs.append("cert normalization %g"%(val-1))
        return errs,{}
    else:
        errs.append("bad status")
        return errs,{}
